-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Clearly trivial misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is a "clearly trivial" misstatement?', '["A misstatement below a threshold where accumulation is unnecessary because such amounts are inconsequential to the financial statements", "A misstatement that falls below the overall materiality level set for the engagement", "A misstatement that management has already corrected before the end of fieldwork", "A misstatement identified in a nonmaterial account balance"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial misstatements are those that are inconsequential whether taken individually or in aggregate, judged by size, nature, and circumstances. This threshold is set well below materiality so the auditor need not accumulate such amounts. However, a misstatement merely below overall materiality (choice B) may still require accumulation because individually immaterial items can be material in aggregate.', 'easy', 1),

-- Q2: medium / L3 — Effect of IT general control deficiency on application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Manufacturing, the engagement team discovers that the IT department failed to apply critical database security patches for nine months and programmers had unrestricted access to production data. What is the most likely effect on the auditor''s assessment of automated application controls?', '["The auditor should issue an adverse opinion on internal control without further testing", "The auditor should evaluate whether the IT general control weakness undermines the reliability of all automated application controls that depend on the database", "The auditor should limit testing exclusively to manual controls and exclude all automated controls", "The auditor should require management to reprocess all transactions before completing the audit"]'::jsonb, 1, 'Under AU-C 315.A72, IT general controls support the continued proper functioning of application controls. When IT general controls such as access security and change management are deficient, the auditor cannot rely on automated controls that depend on the compromised environment. However, issuing an adverse opinion without further testing (choice A) is incorrect because the auditor must first assess the actual impact on application control effectiveness.', 'medium', 3),

-- Q3: hard / L4 — Iron curtain vs rollover approach for evaluating misstatements
(1, 'Misstatements and Control Deficiencies', 'Birchfield Industries has $12,000 in prior-year uncorrected misstatements that reverse in the current year and $18,000 in new current-year misstatements. Overall materiality is $25,000. Under the iron curtain approach, the balance sheet misstatement is $18,000; under the rollover approach, the income statement impact is $6,000. The auditor should:', '["Correct all misstatements because the rollover amount exceeds performance materiality", "Accept the financial statements because both approaches yield amounts below materiality", "Evaluate both approaches and use professional judgment to determine which better reflects the substance of the misstatements in the context of the financial statements as a whole", "Use only the iron curtain approach because it is always the more conservative method"]'::jsonb, 2, 'Under AU-C 450.11 and SEC SAB 108 guidance, auditors should consider both the iron curtain and rollover approaches when evaluating uncorrected misstatements. Neither method alone may capture the full effect because each can mask errors the other reveals. While choice B suggests accepting the statements because both amounts fall below materiality, this ignores qualitative factors and the potential cumulative impact across periods.', 'hard', 4),

-- Q4: medium / L3 — Effect of management bias on misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'Maple Ridge Electronics has several uncorrected misstatements totaling $30,000, all of which overstate net income. Overall materiality is $75,000. The auditor notes that every misstatement favors management''s bonus targets. What is the most likely effect on the auditor''s evaluation?', '["The misstatements require no further consideration because they are well below materiality", "The auditor should consider only the quantitative effect since the total is less than half of materiality", "The auditor should disregard the directional pattern because each misstatement individually is clearly trivial", "The auditor should consider whether the consistent direction indicates management bias, which may signal that additional undetected misstatements exist"]'::jsonb, 3, 'Under AU-C 450.A16, when all uncorrected misstatements favor management, the auditor should consider whether the pattern indicates bias. Even if the aggregate is quantitatively immaterial, directional consistency raises the risk that the financial statements are materially misstated when combined with undetected misstatements. While choice A suggests no further consideration is needed, this disregards the qualitative evaluation required by the standard.', 'medium', 3),

-- Q5: medium / L3 — Effect of prior-period uncorrected misstatements on current opinion
(1, 'Misstatements and Control Deficiencies', 'Granite Peak Construction had $35,000 in uncorrected prior-year misstatements. In the current year, the auditor identifies $28,000 in new misstatements. Overall materiality remains $50,000. How should the auditor analyze the combined effect on the current-year financial statements?', '["The auditor should evaluate whether the prior-year carryover effect combined with current-year misstatements causes a material misstatement of the current-year financial statements", "The auditor should disregard the prior-year misstatements because they were evaluated and accepted in the previous audit", "The auditor should require restatement of the prior-year financial statements before issuing the current-year opinion", "The auditor should consider only current-year misstatements because AU-C 450 applies prospectively to each engagement"]'::jsonb, 0, 'Under AU-C 450.06, the auditor must consider the effect of uncorrected misstatements from prior periods on the current-year financial statements. Prior-year misstatements may affect current-period balances through opening balances or reversal effects. However, choice B is incorrect because disregarding prior-year misstatements ignores that balance sheet errors carry forward and can cause current-year statements to be materially misstated.', 'medium', 3),

-- Q6: medium / L3 — Deficiency in operation identified through sample testing
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Valley Healthcare, the auditor discovers that the entity has a documented policy requiring dual authorization for disbursements over $10,000. Review of 40 sampled transactions reveals that 8 lacked the required second signature. What is the most likely classification?', '["A deficiency in design because the policy threshold is too high for the entity''s transaction volume", "A material weakness because 20% of sampled transactions were noncompliant", "A control environment failure requiring immediate withdrawal from the engagement", "A deficiency in operation because the control is properly designed but is not operating effectively as intended"]'::jsonb, 3, 'Under AU-C 265.A5, a deficiency in operation exists when a properly designed control does not operate as intended or when the person performing it lacks competence or authority. The dual-authorization policy is suitably designed, but the 20% deviation rate shows it is not consistently applied. In contrast, a design deficiency (choice A) would mean the control itself was inadequate, which is not the case here.', 'medium', 3),

-- Q7: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is a deficiency in the design of internal control?', '["A control that fails to operate consistently due to staff turnover", "A control that produces misstatements but is promptly corrected by management", "A control that is missing or not suitably designed to prevent or detect misstatements on a timely basis", "A control that was effective in prior periods but has not been updated for new risks"]'::jsonb, 2, 'Under AU-C 265.07, a deficiency in design exists when a necessary control is missing or when an existing control is not suitably designed such that even if it operates as intended, it cannot prevent or detect misstatements on a timely basis. Unlike a design deficiency, a control that fails due to inconsistent execution (choice A) describes a deficiency in operation, because the underlying design may be adequate.', 'easy', 1),

-- Q8: medium / L2 — Communication timing for control deficiency letters
(1, 'Misstatements and Control Deficiencies', 'Ridgeline Consulting Group''s audit was completed on March 15, 2026, and the auditor''s report was released on March 22, 2026. The auditor identified two significant deficiencies during fieldwork. Under AU-C 265, by what date must the written communication of significant deficiencies be issued?', '["Within 30 calendar days of the auditor''s report date", "No later than 60 days after the report release date", "Before the auditor''s report is issued as a precondition for releasing the opinion", "On or before March 22, 2026, the date of the auditor''s report release"]'::jsonb, 1, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. However, choice C is incorrect because the communication need not precede the report; the standard explicitly provides a post-report window to allow time for proper documentation.', 'medium', 2),

-- Q9: medium / L2 — Fraud misstatement requiring governance communication regardless of amount
(1, 'Misstatements and Control Deficiencies', 'Cascade Distributing''s accounts receivable clerk intentionally recorded fictitious sales of $9,500 to conceal a cash theft. The auditor discovers the scheme during confirmation procedures. Overall materiality is $250,000. Under AU-C 240, the auditor should:', '["Project the misstatement across the receivables population to determine aggregate materiality", "Treat the $9,500 as a clearly trivial amount requiring no further action", "Report the matter only if the aggregate of fraud misstatements exceeds performance materiality", "Communicate the fraud to those charged with governance and evaluate the implications regardless of the dollar amount"]'::jsonb, 3, 'Under AU-C 240.40, the auditor must communicate all identified or suspected fraud to those charged with governance on a timely basis, regardless of dollar amount. Fraud involving employees in positions of trust has qualitative significance beyond its quantitative impact. However, choice B is incorrect because treating the amount as clearly trivial ignores the qualitative nature of intentional misstatements arising from fraud.', 'medium', 2),

-- Q10: easy / L2 — Accumulation of misstatements on summary schedule
(1, 'Misstatements and Control Deficiencies', 'Pinecrest Solar LLC''s audit identifies the following uncorrected misstatements: a $4,200 inventory pricing error, a $2,800 accrued liabilities understatement, and a $1,500 prepaid expense overstatement. Under AU-C 450, the auditor should record these on:', '["The engagement letter as scope limitations", "The management representation letter as corrective action items", "The summary of uncorrected misstatements to evaluate their aggregate effect on the financial statements", "The permanent file as recurring control deficiencies"]'::jsonb, 2, 'Under AU-C 450.05, the auditor must accumulate misstatements identified during the audit, other than those that are clearly trivial, on a summary schedule. This allows evaluation of their aggregate effect on the financial statements. However, choice A is incorrect because the engagement letter establishes the terms of the audit rather than serving as a record of audit findings.', 'easy', 2),

-- Q11: medium / L2 — Lack of segregation of duties as indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'Thornfield Hospitality Group''s controller prepares bank reconciliations, approves wire transfers, and maintains the general ledger with no independent oversight. Under AU-C 265, this finding most likely represents:', '["An efficiency recommendation that does not affect internal control over financial reporting", "A deficiency in operation because the controller performed all tasks correctly", "A scope limitation preventing the auditor from expressing an opinion", "An indicator of a material weakness because the absence of segregation of duties creates a reasonable possibility that a material misstatement would not be prevented or detected on a timely basis"]'::jsonb, 3, 'Under AU-C 265.A11, indicators of material weakness include inadequate segregation of duties not compensated by other controls. When one individual controls authorization, custody, and recording, a reasonable possibility exists that material misstatements could go undetected. While choice B notes the controller performed tasks correctly, past accuracy does not mitigate the ongoing risk created by the control gap.', 'medium', 2),

-- Q12: medium / L2 — Documentation requirements for identified misstatements
(1, 'Misstatements and Control Deficiencies', 'Evergreen Analytics Corp.''s auditor identified eight misstatements during the audit, five of which management corrected. Under AU-C 450, the auditor''s workpaper documentation must include:', '["All misstatements accumulated during the audit, the conclusion on whether uncorrected misstatements are material, and management''s written representations about the uncorrected misstatements", "Only the three uncorrected misstatements since corrected misstatements have no further audit relevance", "A list of all misstatements identified but no evaluation of their aggregate effect", "Only misstatements exceeding performance materiality since smaller amounts need not be documented"]'::jsonb, 0, 'Under AU-C 450.14, the auditor must document the clearly trivial threshold, all accumulated misstatements and whether they were corrected, the conclusion on whether uncorrected misstatements are material, and the basis for that conclusion. However, choice B is incorrect because documenting only uncorrected items omits the standard''s requirement to accumulate all identified misstatements for pattern analysis.', 'medium', 2),

-- Q13: hard / L4 — Evaluating intentional immaterial misstatement and fraud risk
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Financial Services, the auditor discovers that the CFO intentionally understated a $22,000 accrual to meet an earnings target. Overall materiality is $200,000. The misstatement is quantitatively immaterial. The auditor should evaluate whether:', '["The misstatement can be accepted because it falls below both materiality and performance materiality", "The intentional nature indicates a risk of management override that may require expanding procedures, reconsidering the reliability of management representations, and communicating the matter to governance", "The misstatement should be projected across the full population to determine if the aggregate exceeds materiality", "The engagement should be terminated immediately because any intentional misstatement requires withdrawal"]'::jsonb, 1, 'Under AU-C 240.36, an intentional misstatement, even if quantitatively immaterial, is qualitatively significant because it indicates management willingness to manipulate financial reporting. The auditor must reconsider the reliability of audit evidence, evaluate the risk of additional undetected fraud, and communicate with governance. However, choice A is incorrect because simply accepting the misstatement as immaterial ignores the qualitative implications of intentional management override.', 'hard', 4),

-- Q14: medium / L2 — Tolerable misstatement relationship to performance materiality
(1, 'Misstatements and Control Deficiencies', 'Lakeview Manufacturing''s auditor is testing accounts receivable using monetary unit sampling. Overall materiality is $150,000 and performance materiality is $112,500. The tolerable misstatement for this substantive test should be set at:', '["Overall materiality of $150,000 to ensure full coverage of the account", "A percentage of the account balance rather than a function of materiality", "An amount at or below performance materiality to allow for undetected misstatements in other accounts and untested population portions", "Exactly 50% of overall materiality per the standard formula for all substantive tests"]'::jsonb, 2, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It should not exceed performance materiality because the auditor needs to allow for undetected misstatements in both sampled and unsampled portions and in other accounts. However, choice A is incorrect because setting tolerable misstatement at overall materiality leaves no margin for aggregation risk across the audit.', 'medium', 2),

-- Q15: medium / L3 — Impact of remediated control deficiency during audit period
(1, 'Misstatements and Control Deficiencies', 'During the audit of Silverton Manufacturing for the year ended December 31, 2025, the auditor discovers that a control over inventory valuation was deficient from January through September. Management implemented a corrective control in October that operated effectively through year-end. What is the most likely effect on the auditor''s evaluation?', '["The deficiency should be disregarded entirely because it was remediated before year-end", "The auditor must classify the finding as a material weakness for the full audit period regardless of remediation", "The auditor should evaluate whether the deficiency during the first nine months could have resulted in misstatements and assess whether the remediated control sufficiently addresses the exposure", "The remediation eliminates the reporting obligation and the auditor need not communicate the deficiency to governance"]'::jsonb, 2, 'Under AU-C 265.A13, the auditor considers the duration and severity of the deficiency when evaluating its significance. A control that was deficient for nine months may have allowed misstatements during that period, and subsequent remediation does not retroactively cure the exposure. However, choice A is incorrect because disregarding the deficiency entirely ignores the risk of misstatement during the period the control was not operating effectively.', 'medium', 3),

-- Q16: hard / L4 — Recommending action when aggregate approaches materiality
(1, 'Misstatements and Control Deficiencies', 'Summit Ridge Pharmaceuticals has aggregate uncorrected misstatements of $88,000. Overall materiality is $100,000 and performance materiality is $75,000. Management refuses to make corrections, citing immateriality. The most appropriate auditor response is to:', '["Evaluate whether additional audit procedures can reduce the risk that remaining undetected misstatements combined with the known uncorrected amount cause the financial statements to be materially misstated", "Accept management''s position because $88,000 is below the $100,000 materiality threshold", "Withdraw from the engagement because management''s refusal constitutes a scope limitation", "Issue an unmodified opinion with an emphasis-of-matter paragraph disclosing the uncorrected misstatements"]'::jsonb, 0, 'Under AU-C 450.11, when uncorrected misstatements approach materiality, the auditor must consider whether undetected misstatements combined with known uncorrected amounts could exceed materiality. The auditor may need to perform additional procedures or request corrections. However, choice B is incorrect because accepting the position simply because the total is below materiality ignores the risk that undetected misstatements push the aggregate above the threshold.', 'hard', 4),

-- Q17: medium / L2 — Communication of deficiencies below significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brookfield Distribution, the auditor identifies three control deficiencies that individually and in combination are less severe than a significant deficiency. Under AU-C 265, the auditor''s communication obligation for these deficiencies is:', '["The auditor has no obligation and is prohibited from communicating deficiencies below significant deficiency level", "The auditor may consider communicating these deficiencies to management based on professional judgment, though it is not required", "The auditor must communicate all identified deficiencies in writing to those charged with governance regardless of severity", "The auditor must include all deficiencies in the management letter as a mandatory professional requirement"]'::jsonb, 1, 'Under AU-C 265.A18, the auditor may choose to communicate deficiencies that are less severe than significant deficiencies to management or those charged with governance. This communication is not required but may be appropriate based on professional judgment. However, choice A is incorrect because the standard permits, rather than prohibits, such voluntary communication at the auditor''s discretion.', 'medium', 2),

-- Q18: hard / L4 — Pervasive misstatement effect on opinion type
(1, 'Misstatements and Control Deficiencies', 'Pacific Coast Energy''s auditor identifies $450,000 in aggregate uncorrected misstatements spread across revenue, inventory, accounts payable, and equity accounts. Overall materiality is $300,000. The misstatements affect multiple financial statement line items and disclosures. The auditor should evaluate whether to issue:', '["A qualified opinion because the misstatements are material to specific individual line items", "An unmodified opinion with an emphasis-of-matter paragraph about the uncorrected amounts", "A disclaimer of opinion because the pervasive misstatements prevent the auditor from forming any conclusion", "An adverse opinion because the misstatements are both material and pervasive, affecting multiple elements of the financial statements"]'::jsonb, 3, 'Under AU-C 705.08, when misstatements are material and pervasive — affecting multiple elements, accounts, or disclosures rather than being confined to specific items — an adverse opinion is appropriate. Pervasiveness distinguishes between a qualified and adverse opinion. While choice A suggests a qualified opinion, that modification would be appropriate only if the misstatements were material but limited to specific elements rather than spread throughout the statements.', 'hard', 4),

-- Q19: medium / L2 — Classification of known vs projected misstatements
(1, 'Misstatements and Control Deficiencies', 'Norton Industrial Supply''s auditor samples 60 purchase transactions and discovers that 4 transactions totaling $6,200 were recorded in the wrong period. The auditor extrapolates the error to the full population of $1,800,000 in purchases. The $6,200 error found in the sample is classified as a:', '["Known misstatement because it represents the actual error identified in items tested", "Projected misstatement because it was found through sampling procedures", "Likely misstatement because the auditor expects similar errors in the untested population", "Judgmental misstatement because the auditor used professional judgment to identify it"]'::jsonb, 0, 'Under AU-C 450.A4, a known misstatement (also called a factual misstatement) is a misstatement about which there is no doubt — it is the actual error identified in items examined. The extrapolated amount beyond the sample is the projected misstatement. However, choice B is incorrect because a projected misstatement refers to the auditor''s best estimate of total error in the population, not the specific errors found in the sample.', 'medium', 2),

-- Q20: medium / L2 — Management representation letter content on misstatements
(1, 'Misstatements and Control Deficiencies', 'Alder Creek Manufacturing''s auditor has completed the evaluation of uncorrected misstatements and requests a management representation letter. Under AU-C 580 and AU-C 450, the representation letter regarding misstatements must include:', '["A statement that no additional misstatements exist beyond those identified during the audit", "An acknowledgment that the effects of uncorrected misstatements are immaterial individually and in aggregate, with a summary of those misstatements attached to or included in the letter", "A commitment by management to correct all identified misstatements within 90 days of the report date", "A certification that all internal controls operated effectively throughout the audit period"]'::jsonb, 1, 'Under AU-C 450.12, the auditor requests that management provide a written representation that it believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. A summary of the uncorrected misstatements is attached. However, choice A is incorrect because management cannot warrant the complete absence of all undetected errors, and the standard does not require such a representation.', 'medium', 2),

-- Q21: hard / L3 — Entity-level control deficiency effect on transaction-level controls
(1, 'Misstatements and Control Deficiencies', 'Westbrook Financial Group''s auditor determines that the board of directors does not exercise effective oversight of the financial reporting process and has not met in six months. The entity''s transaction-level controls over revenue and expenses appear to operate effectively in isolation. What is the most likely effect of the entity-level control deficiency on the auditor''s overall assessment?', '["The auditor should disregard the governance deficiency because the transaction-level controls are operating effectively", "The auditor should consider whether the entity-level deficiency undermines the reliability of the entire control environment, potentially elevating the severity of transaction-level deficiencies that might otherwise appear less significant", "The auditor should test additional samples of transactions to compensate for the governance weakness", "The auditor should communicate the governance issue only in the management letter without affecting the control assessment"]'::jsonb, 1, 'Under AU-C 265.A7, entity-level controls such as the control environment and governance oversight affect the operating effectiveness of transaction-level controls. A pervasive weakness in governance can undermine the reliability of the entire control structure, even when individual process-level controls appear to function. However, choice A is incorrect because disregarding the governance deficiency ignores the foundational role that tone at the top plays in supporting all other controls.', 'hard', 3),

-- Q22: hard / L4 — Evaluating competing positions on control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'Crestwood Energy''s auditor identifies that the revenue recognition process lacks an automated three-way match. Management argues the deficiency is mitigated by monthly manual reviews performed by the controller. The auditor notes the controller reviews are not documented and the controller is also responsible for posting journal entries. The auditor should conclude that:', '["The manual review fully compensates for the missing automated control because the controller has appropriate expertise", "The deficiency is minor because no actual misstatements were identified during the audit period", "Management''s assessment should be accepted because management is responsible for internal control design", "The compensating control is insufficient because it lacks documentation, the controller has incompatible duties, and the combination likely constitutes a significant deficiency or material weakness"]'::jsonb, 3, 'Under AU-C 265.A10, when evaluating whether a compensating control mitigates a deficiency, the auditor considers whether the compensating control operates effectively and is properly designed. An undocumented review performed by someone with incompatible duties does not provide reliable mitigation. However, choice C is incorrect because the auditor must independently evaluate control deficiency severity regardless of management''s characterization.', 'hard', 4),

-- Q23: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what are the three categories of misstatements?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Known misstatements, likely misstatements, and possible misstatements", "Material misstatements, immaterial misstatements, and clearly trivial misstatements", "Quantitative misstatements, qualitative misstatements, and pervasive misstatements"]'::jsonb, 0, 'Under AU-C 450.A3, misstatements are classified as factual (no doubt about the error), judgmental (arising from management''s estimates or selections the auditor considers unreasonable), and projected (the auditor''s best estimate of total misstatement based on extrapolating sample results). Although choice B uses familiar terminology, "known, likely, and possible" is an older classification framework not used in the clarified standards.', 'easy', 1),

-- Q24: easy / L1 — Performance materiality purpose
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of setting performance materiality below overall materiality?', '["To ensure the auditor tests every transaction in the financial statements", "To eliminate the need for professional judgment when evaluating misstatements", "To reduce to an appropriately low level the probability that aggregate uncorrected and undetected misstatements exceed overall materiality", "To establish the threshold for communicating control deficiencies to governance"]'::jsonb, 2, 'Under AU-C 320.09, performance materiality is set below overall materiality to reduce the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality for the financial statements as a whole. It provides a buffer for estimation risk. However, choice B is incorrect because performance materiality itself requires judgment to determine and does not replace professional judgment in the evaluation process.', 'easy', 1),

-- Q25: easy / L1 — Written communication requirement for significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, how must the auditor communicate significant deficiencies and material weaknesses to those charged with governance?', '["Orally during the exit conference with no further documentation required", "In writing, regardless of whether they were previously communicated orally", "Through inclusion in the auditor''s report as a modification to the opinion", "By attaching a summary to the management representation letter"]'::jsonb, 1, 'Under AU-C 265.11, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance, even if the matters were previously discussed orally. Written communication ensures a formal record and reduces the risk of misunderstanding. Although choice A may describe an appropriate preliminary discussion, oral communication alone does not satisfy the standard because it lacks the permanence required for governance oversight.', 'easy', 1),

-- Q26: medium / L3 — Qualitative factors in evaluating immaterial misstatements
(1, 'Misstatements and Control Deficiencies', 'Pinewood Technologies has $15,000 in uncorrected misstatements against overall materiality of $120,000. The misstatements involve the misclassification of operating expenses as capital expenditures, which affects the debt covenant ratio reported to the entity''s primary lender. What is the most likely effect on the auditor''s evaluation?', '["The misstatements are immaterial and require no further evaluation because they are far below the quantitative threshold", "The auditor should project the misstatements to determine if the aggregate exceeds materiality", "The auditor should request that management correct all misstatements regardless of materiality whenever debt covenants are involved", "The auditor should consider the qualitative significance of the misstatements because they affect compliance with a debt covenant, even though the amount is quantitatively immaterial"]'::jsonb, 3, 'Under AU-C 450.A10, the auditor evaluates both quantitative and qualitative aspects of uncorrected misstatements. Misstatements that affect compliance with debt covenants, regulatory requirements, or contractual obligations may be qualitatively material even when quantitatively small. However, choice A is incorrect because concluding that no further evaluation is needed ignores the qualitative factors that may make an otherwise immaterial amount significant to financial statement users.', 'medium', 3),

-- Q27: easy / L1 — Management override of controls as a fraud risk
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 240, why is management override of controls always considered a fraud risk?', '["Because management override occurs in every audit engagement without exception", "Because management has the unique ability to manipulate records and override controls that otherwise appear to operate effectively", "Because override eliminates the need for internal controls entirely", "Because auditing standards prohibit any form of management intervention in the control process"]'::jsonb, 1, 'Under AU-C 240.31, management override is a presumed fraud risk in every audit because management possesses the authority and ability to manipulate accounting records and override established controls, regardless of how well those controls are designed. Although choice A may seem similar, it confuses the presumed risk of override with an assertion that override actually happens universally, which is not what the standard requires.', 'easy', 1),

-- Q28: medium / L3 — Subsequent discovery of misstatement after report release
(1, 'Misstatements and Control Deficiencies', 'After releasing the audit report for Harborview Logistics on February 15, 2026, the auditor discovers on March 10, 2026, that a $180,000 revenue recognition error existed at the balance sheet date. Overall materiality was $150,000. What is the most likely effect on the auditor''s responsibilities?', '["The auditor has no obligation because the report has already been released and the audit is complete", "The auditor should note the matter for consideration in the next annual audit engagement", "The auditor should take steps under AU-C 560 to determine whether the financial statements need revision and whether users relying on the statements need to be informed", "The auditor should issue a revised report with an emphasis-of-matter paragraph but leave the original financial statements unchanged"]'::jsonb, 2, 'Under AU-C 560.14, when the auditor becomes aware after the report release date of facts that existed at the report date and might have caused a modification, the auditor must discuss the matter with management and determine whether the financial statements need revision. However, choice A is incorrect because the standard establishes post-issuance responsibilities for subsequently discovered facts that may affect the previously issued report.', 'medium', 3),

-- Q29: easy / L1 — Difference between clearly trivial and not clearly trivial
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what distinguishes a "not clearly trivial" misstatement from a "clearly trivial" one?', '["A not clearly trivial misstatement exceeds overall materiality", "A not clearly trivial misstatement must be accumulated on the summary of audit differences for further evaluation", "A not clearly trivial misstatement automatically requires a modified audit opinion", "A not clearly trivial misstatement must be corrected by management before the audit can be completed"]'::jsonb, 1, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit other than those that are clearly trivial. A not clearly trivial misstatement exceeds the clearly trivial threshold and must be included on the summary of uncorrected misstatements for aggregate evaluation. However, choice A is incorrect because exceeding overall materiality describes a material misstatement, which is a much higher threshold than not clearly trivial.', 'easy', 1),

-- Q30: easy / L1 — Auditor responsibility for detecting all misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 200, is the auditor responsible for detecting all misstatements in the financial statements?', '["Yes, the auditor must detect every misstatement to issue an unmodified opinion", "Yes, the auditor is required to identify every misstatement before issuing any opinion", "No, the auditor is responsible for obtaining reasonable assurance that misstatements are not material to the financial statements as a whole", "No, the auditor has no responsibility for misstatements because management is solely accountable for accuracy"]'::jsonb, 2, 'Under AU-C 200.06, an audit provides reasonable assurance, which is a high but not absolute level of assurance, that the financial statements as a whole are free from material misstatement. The auditor is not expected to detect every immaterial error. While choice B suggests every misstatement must be found, this overstates the audit objective because inherent limitations of an audit make detection of all misstatements unattainable.', 'easy', 1)

;

COMMIT;
